	@Override
	public List<Error> validateRiskDetails(RiskDetailsSaveReq req) {
		List<Error> errors = new ArrayList<Error>();
		try {
			if (StringUtils.isBlank(req.getBranchCode()) ) {
				errors.add(new Error("01","Branch Code", "Please Enter BranchCode"));
			}
			if (StringUtils.isBlank(req.getCreatedBy()) ) {
				errors.add(new Error("02","Created By", "Please Enter CreatedBy"));
			}
			if (StringUtils.isBlank(req.getCustomerId()) ) {
				errors.add(new Error("03","Customer Id", "Please Enter Customer Id"));
			}
			if (StringUtils.isBlank(req.getInsuranceId()) ) {
				errors.add(new Error("04","Insurance Id", "Please Enter Insurance Id"));
			}
			if (StringUtils.isBlank(req.getProductId()) ) {
				errors.add(new Error("05","Product Id", "Please Enter Product Id"));
			}
			if (StringUtils.isBlank(req.getProductName()) ) {
				errors.add(new Error("06","Product Name", "Please Enter Product Name"));
			}
			
			if (req.getRiskList()==null || req.getRiskList().size() <= 0 ) {
				errors.add(new Error("08","Risk List", "Please Select atleast One Risk"));
			} else {
				
				for (RiskListSaveReq data :  req.getRiskList()) {
					
					if (StringUtils.isBlank(data.getRiskId())  ) {
						errors.add(new Error("09","Risk Id", "Please Select atleast One Risk"));
					}
					
					// Domestic Product Validations
					if (req.getProductId().equalsIgnoreCase("4")  ) {
						List<Error> errors2 = domesticRiskDetails(data);
						
						if (errors2.size()>0 ) {
							errors.addAll(errors2);
						}
					}
					
				}
			}
			
			
		} catch (Exception e ) {
			e.printStackTrace();
			log.info("Exception is --->" + e.getMessage());
			errors.add(new Error("01","Common Error", e.getMessage()));
		}
		return errors;
	}
	
	@Override
	public SuccessRes saveRiskDetails(RiskDetailsSaveReq req) {
		SuccessRes  res = new SuccessRes();
		try {
			
			String reqRefNo = "" ;
			Date  entryDate = null ;
			String createdBy = "" ;
			String branch = "" ;
			boolean update = false ;
			List<RiskDetails> findRisks = new ArrayList<RiskDetails>();
			if (StringUtils.isBlank(req.getRequestReferenceNo())  ) {
				// Save
				Long idCount =  repository.countByCustomerId(Integer.valueOf(req.getCustomerId()));
				reqRefNo  = "Ref-" + req.getCustomerId() + "/" +String.valueOf(idCount+1) ; 
				res.setResponse("Saved Successfully");     
				
			} else {
			   // Update
				reqRefNo  = req.getRequestReferenceNo() ;
				findRisks = repository.findByRequestReferanceNoOrderByRiskIdAsc(reqRefNo); 
				update = true ;
				res.setResponse("Updated Successfully");
			}
			
			
			for (RiskListSaveReq data :   req.getRiskList() ) {
				RiskDetails save = new RiskDetails(); 
				
				entryDate = new Date();
				createdBy = req.getCreatedBy() ;
				branch    = req.getBranchCode() ;
				
				if (update == true  ) {
					List<RiskDetails> filterRisk = findRisks.stream().filter(o -> o.getRiskId().equals(Integer.valueOf(data.getRiskId())) ).collect(Collectors.toList());
					if (filterRisk.size()>0  ) {
						entryDate = filterRisk.get(0).getEntryDate(); 
						createdBy = filterRisk.get(0).getCreatedBy();
						branch    = filterRisk.get(0).getBranchCode();
					}
				}
				
				save.setBranchCode(branch);
				save.setCreatedBy(createdBy);
				save.setEntryDate(entryDate);
				save.setRequestReferanceNo(reqRefNo);
				
				save.setCompanyId(req.getInsuranceId());
				save.setCustomerId(Integer.valueOf(req.getCustomerId()));
				save.setProductId(Integer.valueOf(req.getProductId()));
				save.setProductName(req.getProductName());
				save.setUpdatedBy(req.getCreatedBy());
				
				save.setOwnHouseYn(data.getOwnHouseYn());
				save.setRemarks(data.getRemarks());
				save.setUpdatedDate(new Date());
				save.setStatus("Y");
				save.setRiskId(Integer.valueOf(data.getRiskId()));
				
				repository.saveAndFlush(save);
				log.info("Saved Details  is --->" + json.toJson(save) );
			}
			
			
			
		} catch (Exception e) {
			e.printStackTrace();
			log.info("Exception is --->" + e.getMessage());
			return null;
		}
		return res;
	}

	
	public List<Error> domesticRiskDetails(RiskListSaveReq riskReq) {
		List<Error> errors = new ArrayList<Error>();
		try {
			
			if (StringUtils.isBlank(riskReq.getOwnHouseYn())  ) {
				errors.add(new Error("10","Own House Yn", "Please Select Own House Or Rental"));
			}
			
		} catch (Exception e ) {
			e.printStackTrace();
			log.info("Exception is --->" + e.getMessage());
			errors.add(new Error("01","Common Error", e.getMessage()));
		}
		return errors;
	}
